import React, { useState } from 'react';
import './index.css';

const App = () => {
  const [sidebarOpen, setSidebarOpen] = useState(true);

  return (
    <div className="app-container">
      {/* Sidebar */}
      <div className={`sidebar ${sidebarOpen ? '' : 'collapsed'}`}>
        <div className="flex items-center justify-between mb-8">
          {sidebarOpen ? (
            <h1 className="text-xl font-bold">CHART<span className="text-green-400">MAZE</span></h1>
          ) : (
            <h1 className="text-xl font-bold">CM</h1>
          )}
          <button 
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="text-white hover:text-green-400"
          >
            {sidebarOpen ? '✕' : '☰'}
          </button>
        </div>

        <nav>
          <NavItem icon="📘" label="My Rule Book" open={sidebarOpen} active />
          <NavItem icon="➕" label="Add Trades" open={sidebarOpen} />
          {/* Add other nav items */}
        </nav>

        <button className="btn btn-primary mt-4 w-full">
          {sidebarOpen ? 'Login' : '🔑'}
        </button>
      </div>

      {/* Main Content */}
      <div className="main-content">
        <h1 className="text-2xl font-bold text-blue-600 mb-4">
          Welcome to ChartsMaze Trade Journal
        </h1>
        {/* Rest of your content */}
      </div>
    </div>
  );
};

const NavItem = ({ icon, label, open, active = false }) => (
  <div className={`nav-item ${active ? 'active' : ''}`}>
    <span className="nav-icon">{icon}</span>
    {open && <span className="nav-text">{label}</span>}
  </div>
);

export default App;
